<?php
/**
 * Fixed-asset classification and read-only straight-line depreciation.
 *
 * @package TaxoCommerce_Accounting
 */
defined( 'ABSPATH' ) || exit;

final class TCA_Depreciation {
    /**
     * The cost of a fixed asset includes VAT that cannot be recovered.
     * No tax deduction or payment is generated by this calculation.
     *
     * @param object $entry Validated expense row.
     * @return float Cost in EUR or store currency.
     */
    public static function cost( $entry ) {
        $base = (float) $entry->amount_base;
        $vat = (float) $entry->amount_tax;
        $deductible = min( 100.0, max( 0.0, (float) $entry->deductible_pct ) );
        return round( $base + $vat * ( 1 - $deductible / 100 ), 2 );
    }

    /**
     * Calendar-year share, prorated by actual days, including leap years.
     * Cumulative rounding ensures the final year clears every cent.
     *
     * @param object $entry Ledger entry with service_date and useful_life_years.
     * @param int    $year Calendar year to report.
     * @return array|null Calculated cost, annual expense and net book value.
     */
    public static function annual( $entry, $year ) {
        if ( ! in_array( (string) ( $entry->kind ?? '' ), array( 'expense', 'asset' ), true ) ||
            'fixed_asset' !== (string) ( $entry->expense_type ?? '' ) ||
            'validated' !== (string) ( $entry->status ?? '' ) ) {
            return null;
        }
        $date = (string) ( $entry->service_date ?? '' );
        $years = (int) ( $entry->useful_life_years ?? 0 );
        if ( ! preg_match( '/^\d{4}-\d{2}-\d{2}$/', $date ) || ! checkdate( (int) substr( $date, 5, 2 ), (int) substr( $date, 8, 2 ), (int) substr( $date, 0, 4 ) ) ||
            $years < 1 || $years > 50 || $year < 2000 || $year > 2150 ) {
            return null;
        }
        $start = new DateTimeImmutable( $date, new DateTimeZone( 'UTC' ) );
        $end = $start->modify( '+' . $years . ' years' );
        $first = new DateTimeImmutable( sprintf( '%04d-01-01', $year ), new DateTimeZone( 'UTC' ) );
        $next = $first->modify( '+1 year' );
        $days = (int) $start->diff( $end )->days;
        if ( $days < 1 ) {
            return null;
        }
        $cost_cents = (int) round( self::cost( $entry ) * 100 );
        $at_first = max( 0, min( $days, $start->diff( $first )->invert ? 0 : (int) $start->diff( $first )->days ) );
        $at_next = max( 0, min( $days, $start->diff( $next )->invert ? 0 : (int) $start->diff( $next )->days ) );
        $before = (int) round( $cost_cents * $at_first / $days );
        $after = (int) round( $cost_cents * $at_next / $days );
        return array(
            'cost' => $cost_cents / 100,
            'expense' => ( $after - $before ) / 100,
            'accumulated' => $after / 100,
            'remaining' => ( $cost_cents - $after ) / 100,
        );
    }

    /**
     * Validate fixed-asset metadata before saving.
     *
     * @param string $type Current or fixed asset.
     * @param string $date In-service date.
     * @param mixed  $years Years of useful life.
     * @param string $fiscal_date Original purchase date.
     * @return bool
     */
    public static function valid( $type, $date, $years, $fiscal_date ) {
        if ( 'current' === $type ) {
            return true;
        }
        if ( 'fixed_asset' !== $type || ! ctype_digit( (string) $years ) ||
            (int) $years < 1 || (int) $years > 50 || ! tca_valid_date( $date ) ) {
            return false;
        }
        return $date >= $fiscal_date;
    }

    /**
     * Report all active and previously completed assets for the selected year.
     * Does not post journals, create settlements or affect the VAT summary.
     *
     * @param int $year Calendar year.
     * @return array List of records with annual depreciation.
     */
    public static function records( $year ) {
        global $wpdb;
        // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery,WordPress.DB.DirectDatabaseQuery.NoCaching -- Current own-ledger depreciation is calculated read-only.
        $rows = (array) $wpdb->get_results( $wpdb->prepare(
            'SELECT * FROM %i WHERE kind IN (%s, %s) AND expense_type = %s AND status = %s AND service_date <= %s ORDER BY service_date, id LIMIT %d',
            tca_table(), 'expense', 'asset', 'fixed_asset', 'validated', sprintf( '%04d-12-31', $year ), 20000
        ) );
        $report = array();
        foreach ( $rows as $entry ) {
            $values = self::annual( $entry, $year );
            if ( null !== $values ) {
                $report[] = array( 'entry' => $entry, 'values' => $values );
            }
        }
        return $report;
    }

    public static function render( $year ) {
        $records = self::records( $year );
        $year_amount = 0.0;
        echo '<h2>' . esc_html__( 'Fixed asset depreciation', 'taxocommerce-accounting' ) . '</h2>';
        echo '<p class="description">' . esc_html__( 'Straight-line accounting allocation by actual days from the in-service date. Does not change VAT, supplier invoices, bank payments, or determine a statutory tax deduction.', 'taxocommerce-accounting' ) . '</p>';
        echo '<table class="widefat striped"><thead><tr>';
        foreach ( array(
            __( 'Asset', 'taxocommerce-accounting' ),
            __( 'In service', 'taxocommerce-accounting' ),
            __( 'Useful life (years)', 'taxocommerce-accounting' ),
            __( 'Amortizable cost', 'taxocommerce-accounting' ),
            __( 'Annual depreciation', 'taxocommerce-accounting' ),
            __( 'Remaining book value', 'taxocommerce-accounting' ),
        ) as $label ) {
            echo '<th>' . esc_html( $label ) . '</th>';
        }
        echo '</tr></thead><tbody>';
        foreach ( $records as $record ) {
            $e = $record['entry'];
            $v = $record['values'];
            $year_amount += $v['expense'];
            echo '<tr><td>' . esc_html( $e->concept ) . '</td><td>' . esc_html( $e->service_date ) . '</td><td>' .
                esc_html( (string) $e->useful_life_years ) . '</td><td>' . esc_html( tca_money( $v['cost'] ) ) .
                '</td><td>' . esc_html( tca_money( $v['expense'] ) ) . '</td><td>' . esc_html( tca_money( $v['remaining'] ) ) . '</td></tr>';
        }
        if ( ! $records ) {
            echo '<tr><td colspan="6">' . esc_html__( 'No validated fixed assets for this year.', 'taxocommerce-accounting' ) . '</td></tr>';
        }
        echo '</tbody></table><p><strong>' . esc_html__( 'Total annual depreciation:', 'taxocommerce-accounting' ) . '</strong> ' .
            esc_html( tca_money( $year_amount ) ) . '</p>';
    }
}
